def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos2(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [sign(b[0] - a[0]), sign(b[1] - a[1])]

    def step_away(a, b):
        return [sign(a[0] - b[0]), sign(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos2(observation.get("self_position", (0, 0)))
    opp_pos = pos2(observation.get("opponent_position", self_pos))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        corners = [c for c in corners if c[0] >= 0 and c[1] >= 0]
        if corners:
            target = max(corners, key=lambda c: dist(c, opp_pos))
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = None
        best_score = None
        for t in targets:
            p = pos2(t, None)
            if p is None:
                continue
            score = dist(self_pos, p) - 0.35 * dist(opp_pos, p)
            if best is None or score < best_score:
                best = p
                best_score = score
        if best is not None:
            return step_toward(self_pos, best)
        return step_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_cells") or []
    best = None
    best_score = None
    for r in resources:
        p = pos2(r, None)
        if p is None:
            continue
        score = dist(self_pos, p) + 0.5 * max(0, 3 - dist(opp_pos, p))
        if best is None or score < best_score:
            best = p
            best_score = score
    if best is not None:
        return step_toward(self_pos, best)

    return step_away(self_pos, opp_pos)

